// Author: MiYu. Development integration driver for real AI sources, private globals and live paid orders.
#include "session.h"
#include "setup.h"
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){try{if(argc<3 || argc>5)throw std::runtime_error("Usage: war3_ai_tests <data-root> <map> [race 0..3] [seconds 1..60] | <data-root> <map> duel");if(argc==4 && std::wstring_view(argv[3])==L"duel"){Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,{}, {},0x69707365u);session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(0,2) || !setup.race(1,3))throw std::runtime_error("Unable to set duel races");session.applySetup(setup);session.startMain();auto& vm=session.runtime();vm.invoke("StartMeleeAI",std::array{vm.handle("player",0x100000),vm.string("orc.ai")});if(!session.ais()[0] || !session.ais()[1])throw std::runtime_error("Both source AIs did not start");unsigned initialBuildings=0;for(auto& [id,u]:session.units())if(u->owner==0 && u->building && std::bit_cast<float>(u->life.bits())>0)++initialBuildings;if(!initialBuildings)throw std::runtime_error("Orc base missing");for(unsigned n=0;n<70 && !session.results()[0] && !session.results()[1];++n)session.advance(60);unsigned remainingBuildings=0;for(auto& [id,u]:session.units())if(u->owner==0 && u->building && std::bit_cast<float>(u->life.bits())>0)++remainingBuildings;if(!session.results()[0] || *session.results()[0]!=1 || !session.results()[1] || *session.results()[1]!=0 || remainingBuildings)throw std::runtime_error("Source AI duel did not reach expected defeat and victory");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS original_ai_orc_undead_duel seed=1768977253 initial_orc_buildings="<<initialBuildings<<" remaining="<<remainingBuildings<<" elapsed="<<session.simulationTime()<<" game_dll_loaded=false\nRESULT passed=1 failed=0\n";return 0;}unsigned race=argc>3?unsigned(std::stoi(argv[3])):0;double duration=argc>4?std::stod(argv[4]):2;if(race>3 || duration<=0 || duration>60)throw std::runtime_error("Invalid integration arguments");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,race+1))throw std::runtime_error("Unable to set integration race");session.applySetup(setup);session.startMain();if(!session.ais()[1])throw std::runtime_error("Original map main did not start computer AI");session.advance(duration);auto& ai=*session.ais()[1];unsigned orders=0,queues=0,gathering=0,builds=0;for(auto& [id,u]:session.units())if(u->owner==1){orders+=u->currentOrder!=0;queues+=unsigned(u->production.size());gathering+=u->gather.phase!=GatherOrder::Phase::None;builds+=u->buildOrder.has_value() || u->construction.has_value();}bool developing=!ai.towns.empty() && session.runtime().threadCount() && (queues || builds);if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<(developing?"PASS":"FAIL")<<" source_ai file="<<ai.file<<" origin="<<ai.origin<<" towns="<<ai.towns.size()<<" orders="<<orders<<" queues="<<queues<<" gathering="<<gathering<<" builds="<<builds<<" threads="<<session.runtime().threadCount()<<" elapsed="<<session.simulationTime()<<" game_dll_loaded=false\n";if(!developing)throw std::runtime_error("AI did not reach a live town and paid development orders");return 0;}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
